import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel: computes C = A * B where A is (M, K) and B is (K, M),
# with K being small ("tall and skinny" case). Each block handles one row
# of A (cached in shared memory) and a chunk of columns of B/C.
cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define MAX_K 128
#define BLOCK_ROWS 8
#define BLOCK_COLS 64
#define VEC 4
#define THREADS (BLOCK_COLS / VEC)
__global__ void tall_skinny_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int K)
{
    __shared__ float sA[BLOCK_ROWS][MAX_K];
    __shared__ float sB[MAX_K][BLOCK_COLS];
    int row_base = blockIdx.x * BLOCK_ROWS;
    int col_base = blockIdx.y * BLOCK_COLS;
    int tid = threadIdx.x; // 0..THREADS-1
    // Cooperatively load the A tile (BLOCK_ROWS x K) into shared memory.
    for (int idx = tid; idx < BLOCK_ROWS * K; idx += THREADS) {
        int r = idx / K;
        int k = idx % K;
        int global_row = row_base + r;
        sA[r][k] = (global_row < M) ? A[global_row * K + k] : 0.0f;
    }
    int col = col_base + tid * VEC;
    // Cooperatively load the B tile (K x BLOCK_COLS) into shared memory using vectorized loads.
    for (int k = 0; k < K; ++k) {
        if (col + VEC - 1 < M) {
            float4 bvec = *reinterpret_cast<const float4*>(&B[k * M + col]);
            sB[k][tid * VEC + 0] = bvec.x;
            sB[k][tid * VEC + 1] = bvec.y;
            sB[k][tid * VEC + 2] = bvec.z;
            sB[k][tid * VEC + 3] = bvec.w;
        } else {
            #pragma unroll
            for (int c = 0; c < VEC; ++c) {
                int cc = col + c;
                sB[k][tid * VEC + c] = (cc < M) ? B[k * M + cc] : 0.0f;
            }
        }
    }
    __syncthreads();
    float acc[BLOCK_ROWS][VEC];
    #pragma unroll
    for (int r = 0; r < BLOCK_ROWS; ++r) {
        #pragma unroll
        for (int c = 0; c < VEC; ++c) {
            acc[r][c] = 0.0f;
        }
    }
    for (int k = 0; k < K; ++k) {
        float b0 = sB[k][tid * VEC + 0];
        float b1 = sB[k][tid * VEC + 1];
        float b2 = sB[k][tid * VEC + 2];
        float b3 = sB[k][tid * VEC + 3];
        #pragma unroll
        for (int r = 0; r < BLOCK_ROWS; ++r) {
            float aval = sA[r][k];
            acc[r][0] += aval * b0;
            acc[r][1] += aval * b1;
            acc[r][2] += aval * b2;
            acc[r][3] += aval * b3;
        }
    }
    #pragma unroll
    for (int r = 0; r < BLOCK_ROWS; ++r) {
        int global_row = row_base + r;
        if (global_row < M) {
            #pragma unroll
            for (int c = 0; c < VEC; ++c) {
                int cc = col + c;
                if (cc < M) {
                    C[global_row * M + cc] = acc[r][c];
                }
            }
        }
    }
}
torch::Tensor tall_skinny_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");
    A = A.contiguous();
    B = B.contiguous();
    int M = A.size(0);
    int K = A.size(1);
    TORCH_CHECK(B.size(0) == K, "Inner dimensions must match");
    TORCH_CHECK(B.size(1) == M, "Output must be square (M x M) for this kernel");
    TORCH_CHECK(K <= MAX_K, "K too large for shared memory buffer");
    auto C = torch::empty({M, M}, A.options());
    dim3 block(THREADS);
    dim3 grid((M + BLOCK_ROWS - 1) / BLOCK_ROWS, (M + BLOCK_COLS - 1) / BLOCK_COLS);
    tall_skinny_matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );
    return C;
}
"""

cpp_source = r"""
torch::Tensor tall_skinny_matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

tall_skinny_matmul = load_inline(
    name="tall_skinny_matmul",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["tall_skinny_matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model using a custom CUDA kernel for the tall-and-skinny
    matrix multiplication C = A * B, where A is (M, K), B is (K, M),
    and K << M.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_fn = tall_skinny_matmul.tall_skinny_matmul_cuda

    def forward(self, A, B):
        A = A.cuda().contiguous()
        B = B.cuda().contiguous()
        return self.matmul_fn(A, B)


M = 16384 * 2
N = 16 * 2

def get_inputs():
    A = torch.rand(M, N)
    B = torch.rand(N, M)
    return [A, B]

def get_init_inputs():
    return []

